class C
{
    private C(string s, ref int i) => System.Console.WriteLine("string" + i);
    private C(object o, in int i) => System.Console.WriteLine("object" + i);
    static void Main()
    {
        int i = 5;
        new C(default(object), ref i);
    }
}

